import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();if(s.trap(new int[]{0,1,0,2,1,0,1,3,2,1,2,1})!=6||s.trap(new int[]{4,2,0,3,2,5})!=9)throw new AssertionError();Random r=new Random(7);for(int t=0;t<2000;t++){int n=1+r.nextInt(40);int[] a=new int[n];for(int i=0;i<n;i++)a[i]=r.nextInt(20);int w=0;for(int i=0;i<n;i++){int l=0,h=0;for(int j=0;j<=i;j++)l=Math.max(l,a[j]);for(int j=i;j<n;j++)h=Math.max(h,a[j]);w+=Math.min(l,h)-a[i];}if(s.trap(a)!=w)throw new AssertionError();}int[] max=new int[20000];max[0]=max[max.length-1]=100000;if(s.trap(max)!=1999800000)throw new AssertionError();System.out.println("Samples and original edge/reference checks passed");}}